        /// <summary>(item class, class set), every modifiable class once.</summary>
        public static IEnumerable<(uint ClassId, uint ClassSetId)> ModifiableClasses =>
            Armor.Select(classId => (classId, ArmorClassSet))
                .Concat(Weapons.Select(classId => (classId, WeaponClassSet)))
                .Concat(Tools.Select(classId => (classId, ToolClassSet)));

        /// <summary>Rows to an insert: ten thousand statements of one row each are slow on MySQL.</summary>
        private const int RowsPerInsert = 250;

        private static IEnumerable<string> Inserts(string into, IEnumerable<string> rows)
        {
            var batch = new List<string>(RowsPerInsert);

            foreach (var row in rows)
            {
                batch.Add(row);

                if (batch.Count < RowsPerInsert)
                    continue;

                yield return $"insert into {into} values {string.Join(", ", batch)};";
                batch.Clear();
            }

            if (batch.Count > 0)
                yield return $"insert into {into} values {string.Join(", ", batch)};";
        }

        public static IEnumerable<string> InsertStatements =>
            Inserts($"{ModuleItemEntry.TableName} (id, module_id, strength)", Items.Select(row => $"({row.ItemTemplateId}, {row.ModuleId}, {row.Strength})"))
                .Concat(Inserts($"{ModifiableClassEntry.TableName} (id, class_set_id)", ModifiableClasses.Select(row => $"({row.ClassId}, {row.ClassSetId})")));
    }
